请对以下 case 进行三维加权评分。

=== case_id ===
Case-11-fitness-015

=== 用户原始指令 (query.txt) ===
运动目标卡,中间圆环显示今日完成度,上面写"目标已达成",整卡用运动风格渐变当氛围背景,不要图片纯文字色块,下面纵向排三个数据(步数、卡路里、时长)。跳到运动健康App,数据用静态示例,简洁设计。

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "运动目标卡,中间圆环显示今日完成度,上面写\"目标已达成\",整卡用运动风格渐变当氛围背景,不要图片纯文字色块,下面纵向排三个数据(步数、卡路里、时长)。跳到运动健康App,数据用静态示例,简洁设计。",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "huaweischeme://healthapp/home/sport?sportType=2"
      }
    }
  ],
  "dataModelSchema": {
    "fitness": {
      "statusText": {
        "type": "string",
        "description": "今日运动目标完成状态文案。",
        "sampleValue": "目标已达成"
      },
      "progress": {
        "value": {
          "type": "number",
          "description": "今日运动目标完成度数值。",
          "sampleValue": 86
        },
        "total": {
          "type": "number",
          "description": "今日运动目标完成度总量。",
          "sampleValue": 100
        },
        "percentText": {
          "type": "string",
          "description": "今日运动目标完成度百分比展示文本。",
          "sampleValue": "86%"
        },
        "caption": {
          "type": "string",
          "description": "进度环下方的简短说明。",
          "sampleValue": "今日完成度"
        }
      },
      "metrics": {
        "steps": {
          "valueText": {
            "type": "string",
            "description": "今日步数展示文本。",
            "sampleValue": "12680步"
          }
        },
        "calories": {
          "valueText": {
            "type": "string",
            "description": "今日消耗卡路里展示文本。",
            "sampleValue": "520千卡"
          }
        },
        "duration": {
          "valueText": {
            "type": "string",
            "description": "今日运动时长展示文本。",
            "sampleValue": "48分钟"
          }
        }
      }
    }
  },
  "assetCandidates": []
}

